{"implementation":"def solve(case):
    threshold = case["threshold"]
    accepted_call_ids = []
    diagnostics = []
    for call in case["calls"]:
        normalized_gain = (call["loss_without_call"] - call["loss_with_call"]) / call["prediction_tokens"]
        accepted = bool(call["parseable"] and normalized_gain >= threshold)
        diagnostic = {
            "accepted": accepted,
            "call_id": call["call_id"],
            "normalized_gain": normalized_gain,
        }
        diagnostics.append(diagnostic)
        if accepted:
            accepted_call_ids.append(call["call_id"])
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }"}
